-- Rewritten tier proposals and follow-ups (longer, structured, tier-specific).
-- Runs once (tracked in app_migrations), so later edits made in the admin are never overwritten.

create table if not exists public.app_migrations (name text primary key, applied_at timestamptz not null default now());
alter table public.app_migrations enable row level security;

do $$ begin
  if exists (select 1 from public.app_migrations where name = '0012_tier_templates_v2') then return; end if;
  update public.email_templates set subject = E'Clean Truck Check done at your truck, {{first_name}}', body = E'Hi {{first_name}},\n\nWhen you run one truck, there is no backup. Every hour spent driving to a test site and waiting in line is an hour the truck is not earning, and CARB''s Clean Truck Check is one more deadline sitting on your plate next to loads, fuel, maintenance and invoices.\n\nMiss the window and the DMV can hold your registration, with possible CARB citations on top. That is a hard way to find out a test was due.\n\nDiesel Dynamix does the test where your truck is parked. We come to your home, yard or jobsite anywhere in Southern California, including the Ports of LA and Long Beach.\n\n### How it works\n\n1. Reply or text with your truck year and where it sits.\n2. We come out at a time that works for you, including early morning before you roll.\n3. We run the CARB-verified OBD test (2013 and newer) or the smoke opacity test plus visual inspection (2012 and older), explain the result in plain English and tell you your next due date.\n\n> Most covered trucks test twice a year right now. We send you a reminder before the next round so it never sneaks up on you, and if CTC-VIS reporting has been a headache, we can help you figure that out too.\n\nWant it handled? Reply with your truck year and city, or book a visit here:\n\n{{book_button}}\n\nKameron\nDiesel Dynamix\n(858) 342-8328\n\n{{whatsapp_button}}' where id = '6f1b2a10-0000-4000-8000-000000000101';
  update public.email_templates set subject = E'{{company}}: every truck tested in one yard visit', body = E'Hi {{first_name}},\n\nWith two or three trucks, you are the dispatcher, the mechanic, the bookkeeper and the compliance department. Clean Truck Check due dates rarely line up, so trucks end up going to a test site one at a time, and each trip costs you a driver and half a day.\n\nThe real risk is that one truck slips through. A single missed test can put a hold on that truck''s DMV registration and open the door to CARB citations, and suddenly a third of your fleet is parked.\n\nDiesel Dynamix tests your whole fleet at your yard in one visit, anywhere in Southern California, from LA and the ports to the Inland Empire and San Diego.\n\n### What you get\n\n- Every truck tested in one stop, mixed fleets included (OBD test for 2013 and newer, smoke opacity plus visual inspection for 2012 and older)\n- Early-morning visits so the trucks still leave on time\n- Results explained in plain English, with the next due date for each truck\n- Reminders before the next round, and help with CTC-VIS reporting if you need it\n- Recurring visits on a set schedule if you would rather not think about it again\n\n> A DMV registration hold can keep a California-registered truck from renewing until it is back in compliance. For a small carrier, that is a direct hit to revenue. One scheduled yard visit removes that risk for every truck at the same time.\n\nReply with your truck count and yard location and I will come back with a time, or book straight in:\n\n{{book_button}}\n\nKameron\nDiesel Dynamix\n(858) 342-8328\n\n{{whatsapp_button}}' where id = '6f1b2a10-0000-4000-8000-000000000102';
  update public.email_templates set subject = E'Clean Truck Check without pulling trucks off routes', body = E'Hi {{first_name}},\n\nOnce a fleet reaches four to ten trucks, Clean Truck Check stops being a chore and becomes a scheduling problem. Every test site trip means a unit off a route, a driver tied up and dispatch working around the gap, and the due dates are scattered across the year.\n\nMiss one and that truck''s DMV registration can be held, with CARB citations on top. Tracking it all in a spreadsheet works right up until the week it does not.\n\nDiesel Dynamix runs the program at your yard instead. We cover all of Southern California, including the Ports of LA and Long Beach.\n\n### How we handle a fleet\n\n1. You send us your truck list (year and VIN is enough) and your yard location.\n2. We schedule recurring visits around your operation, early mornings included, and test every due truck in one stop.\n3. You get results explained plainly, a compliance record per truck and VIN, the next due date for each unit and a reminder before the next round.\n\n> Under CARB''s current rule, OBD-equipped trucks move from two tests a year to four starting October 1, 2027. A bill has proposed cutting that back, so it may change, but either way a fleet your size will have more test events to track, not fewer.\n\nReply with your truck count and yard city and I will map out what a recurring schedule would look like for {{company}}, or book a first visit:\n\n{{book_button}}\n\nKameron\nDiesel Dynamix\n(858) 342-8328\n\n{{whatsapp_button}}' where id = '6f1b2a10-0000-4000-8000-000000000103';
  update public.email_templates set subject = E'Clean Truck Check program for {{company}}', body = E'Hi {{first_name}},\n\nAt the scale {{company}} operates, Clean Truck Check is not a test, it is a program: units spread across yards, due dates that never line up, and a record for every VIN that has to hold up if CARB or an auditor asks. Running that through walk-in test sites, one truck at a time, is where fleets lose control of it.\n\nThe cost of a gap is concrete. Each missed truck means a possible DMV registration hold plus exposure to CARB citations and penalties.\n\nDiesel Dynamix provides mobile CTC testing across Southern California, from the Ports of LA and Long Beach through the Inland Empire to San Diego and El Centro, as one accountable vendor.\n\n### What a fleet program includes\n\n- Recurring on-site visits at each yard, scheduled around dispatch, with early-morning windows\n- Mixed-fleet testing: CARB-verified OBD tests for 2013 and newer diesels, smoke opacity plus visual inspection for older units, alt-fuel trucks covered as well\n- A compliance record per truck and VIN, kept current, so your audit file is always ready\n- Due-date tracking and reminders before each round, plus support with CTC-VIS reporting\n- One point of contact who is accountable for the whole program\n\n> Under CARB''s current rule, OBD-equipped trucks go from two tests a year to four on October 1, 2027. A bill has proposed reducing that, but a fleet of your size should plan for the volume to rise, not fall.\n\nI would like 15 minutes with you or whoever owns fleet compliance to walk through unit count, yard locations and timing. Pick a slot here:\n\n{{book_button}}\n\nKameron\nDiesel Dynamix\n(858) 342-8328\n\n{{whatsapp_button}}' where id = '6f1b2a10-0000-4000-8000-000000000104';
  update public.email_templates set subject = E'Re: Clean Truck Check done at your truck, {{first_name}}', body = E'Hi {{first_name}},\n\nQuick follow-up. One thing worth doing this week: log in to your CARB CTC-VIS account and check the compliance deadline listed for your truck, so you know exactly when your next test is due.\n\nIf it is coming up, or you are not sure where to find it, I can look at it with you and get the test done at your truck in one early-morning stop. You keep your day''s loads.\n\nWould it help if I came out before your next deadline?\n\n{{book_button}}\n\nKameron\nDiesel Dynamix\n(858) 342-8328\n\n{{whatsapp_button}}' where id = '6f1b2a10-0000-4000-8000-000000000201';
  update public.email_templates set subject = E'Re: {{company}}: every truck tested in one yard visit', body = E'Hi {{first_name}},\n\nFollowing up on testing {{company}}''s trucks in one visit. Here is how a yard visit actually goes: we arrive early, usually before the first truck leaves, plug into each 2013-and-newer unit for the OBD test and run smoke opacity plus a visual inspection on anything older. Trucks go out on schedule. Before we leave, you know which units passed and the next due date for each one.\n\nNo driving around, no half days lost at a test site, no truck forgotten.\n\nWould a single visit for all your trucks be worth 10 minutes to set up?\n\n{{book_button}}\n\nKameron\nDiesel Dynamix\n(858) 342-8328\n\n{{whatsapp_button}}' where id = '6f1b2a10-0000-4000-8000-000000000202';
  update public.email_templates set subject = E'Re: Clean Truck Check without pulling trucks off routes', body = E'Hi {{first_name}},\n\nOne more thought on Clean Truck Check for {{company}}. Fleets your size usually lose track of due dates, not tests. Each truck has its own compliance deadline in CTC-VIS, and they drift apart as units are bought, sold or re-registered.\n\nWhat we do differently is put every unit on one calendar: a record per VIN, the next due date for each truck and a reminder before each round, with the testing done at your yard so dispatch does not have to plan around it.\n\nWould you like me to draft a recurring schedule for your trucks?\n\n{{book_button}}\n\nKameron\nDiesel Dynamix\n(858) 342-8328\n\n{{whatsapp_button}}' where id = '6f1b2a10-0000-4000-8000-000000000203';
  update public.email_templates set subject = E'Re: Clean Truck Check program for {{company}}', body = E'Hi {{first_name}},\n\nFollowing up on the fleet program note. A useful exercise before 2027: take your OBD-equipped unit count and multiply it by four. Under CARB''s current rule, that is how many test events per year your team will need to schedule, record and report from October 2027, twice today''s volume, unless the proposed reduction passes.\n\nThat volume is far easier to manage through one vendor with one set of records across every yard than site by site, truck by truck. That is what we set up.\n\nIs a 15-minute call with you or your compliance manager worth scheduling?\n\n{{book_button}}\n\nKameron\nDiesel Dynamix\n(858) 342-8328\n\n{{whatsapp_button}}' where id = '6f1b2a10-0000-4000-8000-000000000204';
  insert into public.app_migrations (name) values ('0012_tier_templates_v2');
end $$;
